function HostMetric({label,value,sub}:any){return <div className="wt-host-metric rounded-lg p-3"><div className="text-[10px] uppercase tracking-wide text-zinc-500">{label}</div><div className="mt-1 text-lg font-semibold">{value}</div><div className="mt-1 truncate text-[11px] text-zinc-500" title={sub}>{sub}</div></div>}
function HostSummaryPill({label,value,sub}:any){return <div className="wt-host-summary-pill"><div className="text-[9px] font-bold uppercase tracking-[.08em] text-zinc-500">{label}</div><div className="mt-1 text-sm font-semibold">{value}</div><div className="mt-0.5 truncate text-[10px] text-zinc-500" title={sub}>{sub}</div></div>}
function HostActionTile({label,value,sub,actionLabel,onClick,kind='default',disabled=false,stackAction=false,progress}:any){return <div className={`wt-host-action-tile ${stackAction?'is-stacked':''} ${progress?'has-progress':''}`}><div className="min-w-0 flex-1"><div className="wt-host-action-label">{label}</div><div className="wt-host-action-value">{value}</div>{stackAction&&!progress?<Button className="wt-host-action-btn" kind={kind} disabled={disabled} onClick={onClick}>{actionLabel}</Button>:null}<div className="wt-host-action-sub" title={sub}>{sub}</div>{progress?<CleanupProgress op={progress}/>:null}</div>{!stackAction&&!progress?<Button className="wt-host-action-btn" kind={kind} disabled={disabled} onClick={onClick}>{actionLabel}</Button>:null}</div>}
function CleanupProgress({op}:{op:CleanupOperation}){const failed=op.status==='failed',done=op.status==='success'||failed||op.status==='cancelled',pct=Math.max(0,Math.min(100,Number(op.percent||0)));return <div className={`wt-cleanup-progress ${failed?'is-failed':done?'is-done':''}`}><div className="flex items-center justify-between gap-2"><span className="truncate text-[10px] font-medium">{op.stage||'Cleaning…'}</span><span className="wt-mono text-[9px] text-zinc-500">{pct}%</span></div><div className="wt-op-track"><div className="wt-op-bar" style={{width:`${Math.max(3,pct)}%`}}/></div>{failed?<div className="mt-1 truncate text-[9px] text-red-300" title={op.error||'Cleanup failed'}>{op.error||'Cleanup failed'}</div>:null}</div>}
function OperationProgress({op,onCancel}: {op:OperationState,onCancel?:()=>void}){const cancelled=op.status==='cancelled',skipped=op.status==='skipped',done=op.status==='success'||op.status==='failed'||cancelled||skipped,failed=op.status==='failed';return <div className={`wt-op-progress ${failed?'is-failed':done?'is-done':''}`}><div className="flex items-center justify-between gap-2"><span className="truncate text-[11px] font-medium">{op.stage||`${op.kind==='check'?'Checking':op.kind==='rollback'?'Rolling back':'Updating'}…`}</span><span className="wt-mono text-[10px] text-zinc-500">{Math.max(0,Math.min(100,op.percent||0))}%</span></div><div className="wt-op-track"><div className="wt-op-bar" style={{width:`${Math.max(3,Math.min(100,op.percent||0))}%`}}/></div><div className="mt-1 flex items-center justify-between gap-2 text-[10px] text-zinc-500"><span>{cancelled?'Cancelled before execution':skipped?'Held by Preflight':failed?(op.error||'Operation failed'):done?'Completed':op.kind==='check'?'Checking update state':op.kind==='rollback'?'Restoring previous container state':'Applying container update'}</span>{op.status==='queued'&&op.job_id>0&&onCancel?<button type="button" onClick={onCancel} className="shrink-0 rounded-md border border-red-500/30 px-2 py-1 font-medium text-red-300 transition hover:bg-red-500/10">Cancel</button>:null}</div></div>}

