   const [x,hist]=await Promise.all([api<any>(`/api/hosts/${container.policy.host_id}/verification?container=${encodeURIComponent(container.name)}`),api<VerificationHistoryEntry[]>(`/api/verification-history?host_id=${container.policy.host_id}&container=${encodeURIComponent(container.name)}&limit=10`).catch(()=>[])])
   const freshState:VerificationState=x.state||{...runningState,status:result.status,checked_at:result.finished_at||new Date().toISOString(),error:result.error||''}
   setVerificationModal(v=>v&&opKey(v.container)===opKey(container)?{...v,profile:{...(x.profile||profile),checks:Array.isArray(x.profile?.checks)?x.profile.checks:profile.checks},state:freshState,history:Array.isArray(hist)?hist:v.history}:v)
