 const sorted=useMemo(()=>[...all].sort((a,b)=>{const ah=hostName(a.policy.host_id),bh=hostName(b.policy.host_id);if(ah!==bh)return ah.localeCompare(bh);const as=a.stack_name||'~standalone',bs=b.stack_name||'~standalone';if(as!==bs)return as.localeCompare(bs);return a.name.localeCompare(b.name)}),[all,hosts])
