 const protectionTone=(rp:RestorePoint)=>isDegraded(rp)?'red':rp.volume_data_protected?'blue':rp.writable_layer?'green':'yellow'
 const scopeLabel=(rp:RestorePoint)=>{const t=String(rp.data_scope_type||rp.unit_kind||'service').toLowerCase(),k=rp.data_scope_key||rp.unit_key||rp.container_name;if(t==='stack')return `Stack · ${k}`;if(t==='service')return `Service · ${k}`;return `Container · ${k}`}
