 const waitJob=async(rp:RestorePoint,id:number)=>{for(let i=0;i<1200;i++){try{const x:any=await api(`/api/job-status/${id}`);const job:Job=x.job,progress=x.progress||{};setRunning(v=>({...v,[rp.id]:{job_id:id,percent:Number(progress.percent||0),stage:String(progress.stage||job.status||'Working')}}));if(job.status==='success'||job.status==='failed'){setRunning(v=>{const n={...v};delete n[rp.id];return n});await load();notify(job.status==='success'?`${rp.container_name}: rollback completed`:`${rp.container_name}: rollback failed · ${job.error||'unknown error'}`);return}}catch(e:any){setRunning(v=>{const n={...v};delete n[rp.id];return n});notify(e.message);return}await new Promise(r=>window.setTimeout(r,650))}setRunning(v=>{const n={...v};delete n[rp.id];return n});notify(`${rp.container_name}: timed out waiting for rollback`)}
