 const[nameFilter,setNameFilter]=useState(''),[hostFilter,setHostFilter]=useState(0),[typeFilter,setTypeFilter]=useState(''),[containerFilter,setContainerFilter]=useState(''),[stateFilter,setStateFilter]=useState(''),[snapshotFilter,setSnapshotFilter]=useState('')
 const[bulk,setBulk]=useState({active:false,current:0,total:0,name:'',success:0,failed:0})
 const load=async()=>{setLoading(true);const errors:string[]=[];const mergeHost=(hostID:number,rows:BackupUnit[])=>setUnits(prev=>{const next=[...prev.filter(u=>u.host_id!==hostID),...rows];containerConfigMemory=next;return next});const archived=api('/api/container-backups?archived_only=1').then((x:any)=>{const rows:BackupUnit[]=Array.isArray(x.units)?x.units:[];setRetention(Number(x.retention||3));setUnits(prev=>{const liveKeys=new Set(prev.filter(u=>u.live).map(unitId));const merged=[...prev.filter(u=>u.live),...rows.filter(u=>!liveKeys.has(unitId(u)))];containerConfigMemory=merged;return merged})}).catch((e:any)=>errors.push(`Archived configs: ${e.message}`));const tasks=hosts.map((h:Host)=>api(`/api/container-backups?host_id=${h.id}`).then((x:any)=>{const rows:BackupUnit[]=Array.isArray(x.units)?x.units:[];setRetention(Number(x.retention||3));mergeHost(h.id,rows)}).catch((e:any)=>errors.push(`${h.name}: ${e.message}`)));await Promise.allSettled([archived,...tasks]);setLoading(false);if(errors.length)notify(`Container Configs · ${errors.join(' · ')}`)}
 useEffect(()=>{load()},[])
 const unitId=(u:BackupUnit)=>`${u.host_id}:${u.kind}:${u.key}`
 const create=async(u:BackupUnit)=>{setCreating(unitId(u));try{await api('/api/container-backups/snapshot',{method:'POST',body:JSON.stringify({host_id:u.host_id,kind:u.kind,key:u.key})});notify(`Config snapshot created · ${u.name}`);await load()}catch(e:any){notify(e.message)}finally{setCreating('')}}
 const deleteArchived=async(u:BackupUnit)=>{if(u.live)return;const count=(u.snapshots||[]).length;if(!confirm(`Delete archived config “${u.name}” and its ${count} retained snapshot${count===1?'':'s'}?\n\nLinked restore points will expire and their rollback-object protection will be released. This cannot be undone.`))return;setDeleting(unitId(u));try{const x:any=await api(`/api/container-backups/archived?host_id=${u.host_id}&kind=${encodeURIComponent(u.kind)}&key=${encodeURIComponent(u.key)}`,{method:'DELETE'});notify(`Archived config deleted · ${u.name} · ${x.removed_snapshots||0} snapshot${Number(x.removed_snapshots||0)===1?'':'s'}`);await load()}catch(e:any){notify(e.message)}finally{setDeleting('')}}
 const createAll=async()=>{const targets=units.filter(u=>u.live);if(!targets.length)return;if(!confirm(`Create one configuration snapshot for all ${targets.length} live stacks/services?\n\nSnapshots are created sequentially. Retention remains ${retention} per stack/service.`))return;setBulk({active:true,current:0,total:targets.length,name:'Preparing…',success:0,failed:0});let success=0,failed=0;for(let i=0;i<targets.length;i++){const u=targets[i];setBulk({active:true,current:i,total:targets.length,name:`${u.host_name} · ${u.name}`,success,failed});try{await api('/api/container-backups/snapshot',{method:'POST',body:JSON.stringify({host_id:u.host_id,kind:u.kind,key:u.key})});success++}catch{failed++}setBulk({active:true,current:i+1,total:targets.length,name:`${u.host_name} · ${u.name}`,success,failed})}await load();setBulk({active:false,current:targets.length,total:targets.length,name:'Completed',success,failed});notify(`Config snapshot run complete · ${success} created${failed?` · ${failed} failed`:''}`)}
 const dl=(u:BackupUnit,s:BackupSnapshot,format:'zip'|'compose')=>`/api/container-backups/download?host_id=${u.host_id}&kind=${encodeURIComponent(u.kind)}&key=${encodeURIComponent(u.key)}&snapshot=${encodeURIComponent(s.id)}&format=${format}`
 const filtered=units.filter(u=>{const name=`${u.name} ${u.key}`.toLowerCase(),containers=(u.containers||[]).join(' ').toLowerCase();if(nameFilter&& !name.includes(nameFilter.toLowerCase()))return false;if(hostFilter&&u.host_id!==hostFilter)return false;if(typeFilter&&u.kind!==typeFilter)return false;if(containerFilter&&!containers.includes(containerFilter.toLowerCase()))return false;if(stateFilter==='live'&&!u.live)return false;if(stateFilter==='archived'&&u.live)return false;const count=(u.snapshots||[]).length;if(snapshotFilter==='with'&&count===0)return false;if(snapshotFilter==='without'&&count>0)return false;return true})
 const pct=bulk.total?Math.round((bulk.current/bulk.total)*100):0
 return <div className="space-y-6"><div className="wt-page-heading"><div><h1 className="text-2xl font-semibold">Container Configs</h1><p className="mt-1 text-sm text-zinc-500">Downloadable configuration recovery snapshots for Compose stacks and standalone containers across your Docker hosts.</p></div><div className="wt-toolbar"><Button onClick={load} disabled={loading||bulk.active}>{loading?'Refreshing…':'Refresh'}</Button><a href="/api/container-backups/download-all"><Button disabled={bulk.active||!units.some(u=>(u.snapshots||[]).length)}>Download all configs</Button></a><Button kind="primary" onClick={createAll} disabled={loading||bulk.active||!units.some(u=>u.live)}>{bulk.active?'Creating configs…':'Snapshot all configs'}</Button></div></div>
  {bulk.active||bulk.total>0?<Card><div className="flex items-center justify-between gap-3"><div><div className="text-sm font-semibold">Config snapshot progress</div><div className="mt-1 text-xs text-zinc-500">{bulk.active?bulk.name:'Last config snapshot run completed'}</div></div><Badge tone={bulk.failed?'yellow':'blue'}>{bulk.current}/{bulk.total}</Badge></div><div className="mt-3 wt-op-track"><div className="wt-op-bar" style={{width:`${Math.max(bulk.active?3:0,pct)}%`}}/></div><div className="mt-2 flex flex-wrap gap-4 text-xs text-zinc-500"><span>{pct}%</span><span>{bulk.success} created</span><span>{bulk.failed} failed</span></div></Card>:null}
  <div className="grid gap-4 lg:grid-cols-3"><Card><div className="text-xs uppercase tracking-wide text-zinc-500">Retention</div><div className="mt-3 text-3xl font-semibold">{retention}</div><div className="mt-2 text-xs text-zinc-500">snapshots per stack or standalone service</div></Card><Card><div className="text-xs uppercase tracking-wide text-zinc-500">Config scope</div><div className="mt-3 font-semibold">Configuration recovery</div><div className="mt-2 text-xs leading-5 text-zinc-500">Reconstructed Compose configuration, Docker inspect, image metadata and volume/network references.</div></Card><Card><div className="text-xs uppercase tracking-wide text-zinc-500">Automatic config snapshot</div><div className="mt-3 font-semibold">Before every update</div><div className="mt-2 text-xs leading-5 text-zinc-500">Manual and automatic container updates capture configuration before the update; full writable-layer restore points are managed under Container Rollback.</div></Card></div>
  <div className="rounded-2xl border border-amber-500/25 bg-amber-500/5 p-4"><div className="flex flex-wrap items-center gap-2"><Badge tone="yellow">Important</Badge><span className="text-sm font-semibold">Container Configs stores configuration, not container data.</span></div><p className="mt-2 text-xs leading-5 text-zinc-500">Each snapshot contains a <b>reconstructed</b> <span className="mono">compose.yaml</span>, Docker inspect data, image metadata and Docker-object references derived from the active runtime configuration. Runtime environment values may contain secrets. <b>Writable-layer contents, volume contents and databases are not part of these downloadable config snapshots.</b> Full pre-update container restore points are managed separately under <b>Container Rollback</b>. Downloads are restricted to Admin/Owner accounts.</p></div>
  <Card className="overflow-hidden p-0"><div className="wt-table-scroll"><table className="wt-table wt-backup-table"><thead><tr><th>Stack / Service</th><th>Host</th><th>Type</th><th>Containers</th><th>State</th><th>Snapshots · {retention} slots</th><th>Action</th></tr><tr className="wt-filter-row"><th><input value={nameFilter} onChange={e=>setNameFilter(e.target.value)} placeholder="Filter name…" className="wt-table-filter"/></th><th><select value={hostFilter} onChange={e=>setHostFilter(Number(e.target.value))} className="wt-table-filter"><option value={0}>All hosts</option>{hosts.map((h:Host)=><option key={h.id} value={h.id}>{h.name}</option>)}</select></th><th><select value={typeFilter} onChange={e=>setTypeFilter(e.target.value)} className="wt-table-filter"><option value="">All types</option><option value="stack">Stack</option><option value="service">Standalone</option></select></th><th><input value={containerFilter} onChange={e=>setContainerFilter(e.target.value)} placeholder="Filter containers…" className="wt-table-filter"/></th><th><select value={stateFilter} onChange={e=>setStateFilter(e.target.value)} className="wt-table-filter"><option value="">All states</option><option value="live">Live</option><option value="archived">Archived only</option></select></th><th><select value={snapshotFilter} onChange={e=>setSnapshotFilter(e.target.value)} className="wt-table-filter"><option value="">All snapshots</option><option value="with">Has snapshots</option><option value="without">No snapshots</option></select></th><th><span className="text-[10px] text-zinc-500">{filtered.length} shown</span></th></tr></thead><tbody>{filtered.map(u=><tr key={unitId(u)}><td><div className="wt-cell-title">{u.name}</div>{u.stack_type?<div className="wt-cell-sub">{u.stack_type}</div>:null}</td><td><Badge>{u.host_name||hosts.find((h:Host)=>h.id===u.host_id)?.name||`Host ${u.host_id}`}</Badge></td><td><Badge tone={u.kind==='stack'?'blue':'gray'}>{u.kind==='stack'?'Stack':'Standalone'}</Badge></td><td className="max-w-[260px]"><div className="text-xs">{u.container_count}</div><div className="wt-cell-sub truncate" title={(u.containers||[]).join(', ')}>{(u.containers||[]).join(', ')||'—'}</div></td><td>{u.live?<Badge tone="green">Live</Badge>:<Badge tone="yellow">Archived only</Badge>}</td><td className="wt-backup-snapshots-cell"><BackupSlots u={u} dl={dl} retention={retention}/></td><td>{u.live?<Button kind="primary" disabled={!!creating||bulk.active||!!deleting} onClick={()=>create(u)}>{creating===unitId(u)?'Creating…':'Create config'}</Button>:<div className="space-y-2"><div className="text-[10px] text-zinc-500">Archived recovery config</div><Button kind="danger" disabled={!!deleting||bulk.active} onClick={()=>deleteArchived(u)}>{deleting===unitId(u)?'Deleting…':'Delete archived'}</Button></div>}</td></tr>)}</tbody></table></div>{!loading&&filtered.length===0?<Empty text="No stacks/services match the current filters."/>:null}</Card>
 </div>
