 const filtered=updates.filter(h=>(!hostFilter||h.host_id===hostFilter)&&(!q||`${h.container_name} ${h.from_version} ${h.to_version} ${h.actor} ${h.trigger}`.toLowerCase().includes(q.toLowerCase())))
