 const filtered=(jobs as Job[]).filter(j=>(!hostFilter||j.host_id===hostFilter)&&(!statusFilter||j.status===statusFilter)&&(!typeFilter||j.type===typeFilter)&&(!q||`${j.id} ${j.container_name} ${j.trigger} ${j.type}`.toLowerCase().includes(q.toLowerCase())))
