 const tone=(s:string)=>s==='success'?'green':s==='failed'?'red':s==='running'?'blue':s==='queued'||s==='skipped'?'yellow':s==='cancelled'?'gray':'gray'
 const txLabel=(s:string)=>String(s||'').replace(/_/g,' ')
